insert into public.source_archive(id,data) values('originals','{
  "4-STEMI_PatientHx.docx": "PATIENT HISTORYScenario 1 \u2013 Anterior STEMIRPATIENT HISTORYScenario 1 \u2013 Anterior STEMIR\nPATIENT HISTORY\nScenario 1 \u2013 Anterior STEMI\nR\nPATIENT HISTORY\nScenario 1 \u2013 Anterior STEMI\nR\n\n\nPresenting Complaint: \n62-year-old male\nSevere chest pain \n\nHistory of Presenting Complaint\nCentral chest discomfort for 1 hour constantly\nOnset while at rest watching TV\nRadiation to jaw and both arms\nFeels like someone pushing down on his chest\nNausea, diaphoresis, \u201cfeels like something is wrong\u201d\n\nRelevant Additional History (if asked)\u00a0\nExperiencing \u201cheartburn\u201d on exertion last few weeks \nWorse on exertion \u2013 walking up hill to his office, while walking dog etc\nFather had MI in 50s, older brother had CABG a few years ago \n\nPMH\u00a0\nPre-diabetic\nHypertension\nEx-smoker (stopped 40 years ago, limited pack year history <5)\n\nMedications\u00a0\nRamipril\n\nAllergies\u00a0\nNKDA\n\nSocial History\u00a0\nWorks in construction \u2013 office job, no HGV driving \nUsually fit and active, walks dog for miles per day \n\n\n\n\n",
  "1-PE_SimChecklist.docx": "SIMULATION CHECKLISTScenario 3 \u2013 Pulmonary EmbolismRSIMULATION CHECKLISTScenario 3 \u2013 Pulmonary EmbolismR\nSIMULATION CHECKLIST\nScenario 3 \u2013 Pulmonary Embolism\nR\nSIMULATION CHECKLIST\nScenario 3 \u2013 Pulmonary Embolism\nR\n\nSTAGE 1 \u2013 A-E ASSESSMENT\nRR: 22\nSpO2: 92% RA\nHR: 110\nBP: 120/80\nTemp: 37.2\nA-E: Swollen, hot and red left leg.  Mildly breathless.\nLearner Actions\nFaculty Actions\nIntroduce self and confirm patient identity\nSuccinct history taking \nA-E Assessment\nOxygen therapy \n\nSim Leader\nProvide history of shortness of breath and collapse\nIf prompted discuss chest pain, travel, OCP\n\nSim Nurse\nAsk for early differential diagnosis \nPrompt learner to consider analgesia\n\n\n\n\nTransition trigger: structured A-E completed, time elapsed\n\nSTAGE 2 \u2013 Differential Diagnosis/Investigations\nRR: 24\nSpO2: 90% RA\nHR: 122\nBP: 110/70\nTemp: 37.2\nA-E: Swollen, hot and red left leg. Mildly breathless.\nLearner Actions\nFaculty Actions\nInterpretation of ABG\nInterpretation of ECG\nInterpretation of CXR\nDifferential diagnosis that includes PE\nPrescribe analgesia/anti-emetic\nSim Leader\nPatient to complain of discomfort\nIncreasing hypoxia/tachycardia\n\nSim Nurse\nProvide CXR when asked\nProvide ECG when asked\nProvide ABG when asked\nPrompt learner with patient discomfort\nPrompt learner for anti-emetic if sick\nAsk for most likely diagnosis/differential\n\n\nTransition trigger: Investigations complete/interpretation performed, differential given, time elapsed\n\n\n\n\n\n\nSIMULATION CHECKLISTScenario 3 \u2013 Pulmonary EmbolismSIMULATION CHECKLISTScenario 3 \u2013 Pulmonary Embolism\nSIMULATION CHECKLIST\nScenario 3 \u2013 Pulmonary Embolism\nSIMULATION CHECKLIST\nScenario 3 \u2013 Pulmonary Embolism\nSTAGE 3 \u2013 Patient Deterioration/Escalation\nRR: 32\nSpO2: 86% RA\nHR: 135\nBP: 85/55\nTemp: 37.2\nA-E: Swollen, hot and red left leg.  Patient clammy and generally unwell.  Visibly breathless.\nLearner Actions\nFaculty Actions\nRecognise deterioration in patient \nFurther A-E Assessment\nCall for immediate help: 2222\nConsider need for anticoagulation\nConsider IV fluids\nSim Leader\nEscalate hypoxia and tachycardia\nReduce blood pressure\nPatient to become increasingly distressed\n\nSim Nurse\nPrompt learner to recognise patient deterioration\nIf 2222 not called or alternative help sought \u2013 prompt learner that seems to be time critical emergency\n\n\n\nTransition trigger: 2222 call put out, repeat A-E assessment underway, time elapsed\n\nSTAGE 4 \u2013 SBAR Handover/Closing\nRR: 32\nSpO2: 86% RA\nHR: 135\nBP: 85/55\nTemp: 37.2\nA-E: Swollen, hot and red left leg.  Patient clammy and generally unwell.  Visibly breathless.\nLearner Actions\nFaculty Actions\nDeliver SBAR handover\nOffer likely diagnosis\n\nSim Leader\nTake on role of medical registrar arriving\nReceive SBAR handover\nPrompt for differential diagnosis\nPrompt for any missed investigations/interpretation\n\n\nSim Nurse\nReassure patient/acting in background\n\nTransition trigger: Completed handover \u2013 scenario end\n",
  "PTX sim checklist.docx": "SIMULATION CHECKLISTScenario 2 \u2013 Tension PneumothoraxRSIMULATION CHECKLISTScenario 2 \u2013 Tension PneumothoraxR\nSIMULATION CHECKLIST\nScenario 2 \u2013 Tension Pneumothorax\nR\nSIMULATION CHECKLIST\nScenario 2 \u2013 Tension Pneumothorax\nR\n\nSTAGE 1 \u2013 A-E ASSESSMENT\nRR: 20\nSpO2: 93% RA\nHR: 100\nBP: 123/80\nTemp: 36.2\nA-E: Breathless, reduced AE and chest expansion on L side\nLearner Actions\nFaculty Actions\nIntroduce self and confirm patient identity\nSuccinct history taking \nA-E Assessment\nOxygen therapy \nRequests CXR\nRequests ABG\nRequests ECG\n\nSim Leader\nProvide history of acute onset chest pain and shortness of breath\nIf prompted give family history of \u2018connective tissue disorder'', non-smoker, nil trauma.\n\nSim Nurse\nAsk for early differential diagnosis \nPrompt learner to consider analgesia\n\n\n\n\nTransition trigger: completes history and initial A-E, provides differential diagnoses, requests CXR\n\nSTAGE 2 \u2013 Differential Diagnosis/Investigations\nRR: 18\nSpO2: 96% on 4L\nHR: 100\nBP: 120/70\nTemp: 36.4 \nA-E: Mildly breathless, sats stable on O2\nLearner Actions\nFaculty Actions\nInterpretation of T1RF on ABG\nInterpretation of ECG\nDifferential diagnosis that includes PTX\nPrescribe analgesia/anti-emetic\n\nSim Leader\nPatient to complain of discomfort\nAsks for diagnosis and plan\nDrop sats if no O2 therapy given\n\nSim Nurse\nProvide ECG when asked\nProvide ABG when asked\n\n\n\nTransition trigger: Investigations complete/interpretation performed, differential given, time elapsed\n\n\n\n\n\n\nSIMULATION CHECKLISTScenario 2 \u2013 Tension PneumothoraxSIMULATION CHECKLISTScenario 2 \u2013 Tension Pneumothorax\nSIMULATION CHECKLIST\nScenario 2 \u2013 Tension Pneumothorax\nSIMULATION CHECKLIST\nScenario 2 \u2013 Tension Pneumothorax\nSTAGE 3 \u2013 Patient Deterioration/Escalation\nRR: 26\nSpO2: 80% on 4L\nHR: 130\nBP: 90/60\nTemp: 36.3\nA-E: Distressed, R tracheal deviation, no breath sounds on L side\nLearner Actions\nFaculty Actions\nRecognise deterioration in patient \nFurther A-E Assessment\nCall for immediate help: 2222\nRecognises need for immediate needle decompression\nReceives CXR \u2013 accurately interprets as tension PTX\nSim Leader\nEscalate hypoxia and tachycardia, reduce blood pressure (improves to 94% on 15L)\nPatient to become increasingly distressed\nIf students commit to intervention \u2013 \u201cHave you done this before doctor?\u201d\n\nSim Nurse\nPrompt learner to recognise patient deterioration\nProvide CXR\nIf 2222 not called or alternative help sought \u2013 prompt learner that seems to be time critical emergency\nPrepares kit/model for decompression\n\n\n\nTransition trigger: 2222 call put out, repeat A-E assessment underway, commits to decompression, time elapsed\n\nSTAGE 4 \u2013 SBAR Handover, intervention\nRR: 30\nSpO2: 84% on 15L\nHR: 135\nBP: 85/55\nTemp: 36.3\nA-E: As above, increasing hypoxia and haemodynamic instability. Periarrest. \nLearner Actions\nFaculty Actions\nDeliver SBAR handover\nOffers diagnosis of tension PTX\nCompletes needle decompression under supervision of medical registrar\n\nSim Leader\nTake on role of medical registrar arriving\nReceive SBAR handover and differential\nPrompt for any missed investigations/interpretation\nInitiates/supervises decompression\n\n\nSim Nurse\nReassure patient/acting in background\n\nTransition trigger: Completed handover and intervention \u2013 scenario end\n",
  "5-PE_PatientHx.docx": "PATIENT HISTORYScenario 3 \u2013 Pulmonary EmbolismRPATIENT HISTORYScenario 3 \u2013 Pulmonary EmbolismR\nPATIENT HISTORY\nScenario 3 \u2013 Pulmonary Embolism\nR\nPATIENT HISTORY\nScenario 3 \u2013 Pulmonary Embolism\nR\n\n\nPresenting Complaint: \n40-year-old female patient\nCollapse with palpitations\n\nHistory of Presenting Complaint\n3-day history of increasingly unwell with intermittent palpitations and feeling out of breath/exercise intolerance\nExperienced sudden light-headedness and collapsed while out shopping this morning\nWitnessed loss of consciousness for ~10-15 seconds\nRapid recovery, no post-ictal confusion\nNo tongue biting, incontinence or seizure activity\n\nRelevant History (if asked)\u00a0\nReturned from Australia 10 days ago\nTaking combined oral contraceptive pill\nMild pleuritic chest discomfort\n\nPMH\u00a0\nMigraine\n\nMedications\u00a0\nCombined oral contraceptive pill\nSumatriptan PRN\n\nAllergies\u00a0\nNKDA\n\nSocial History\u00a0\nNon-smoker\nLives with husband\n\n\n\n\n",
  "PTx_PatientHx.docx": "PATIENT HISTORYScenario 2 \u2013 Pneumothorax RPATIENT HISTORYScenario 2 \u2013 Pneumothorax R\nPATIENT HISTORY\nScenario 2 \u2013 Pneumothorax \nR\nPATIENT HISTORY\nScenario 2 \u2013 Pneumothorax \nR\n\n\nPresenting Complaint: \n23-year-old male\nSevere chest pain \n\nHistory of Presenting Complaint\nSudden onset pain 2 hours ago\nSharp and left sided with no radiation\nWorse on inspiration\nTried paracetamol without improvement\nPain 7/10\nWorried as now short of breath while talking, walking into ED, climbing stairs\n\nRelevant Additional History (if asked)\u00a0\nFather had \u201cconnective tissue problem\u201d and suddenly died when he was younger\nSemi-professional basketball player\n\nPMH\u00a0\nNil\n\nMedications\u00a0\nOTC Paracetamol\n\nAllergies\u00a0\nNKDA\n\nSocial History\u00a0\nNon-smoker\nWorks as a PE teacher\nDriver\nNo alcohol\n\n\n\n\n",
  "3-STEMI-sim-checklist.docx": "SIMULATION CHECKLISTScenario 1 \u2013 Anterior STEMIRSIMULATION CHECKLISTScenario 1 \u2013 Anterior STEMIR\nSIMULATION CHECKLIST\nScenario 1 \u2013 Anterior STEMI\nR\nSIMULATION CHECKLIST\nScenario 1 \u2013 Anterior STEMI\nR\n\nSTAGE 1 \u2013 History and A-E Assessment\nRR: 18\nSpO2: 95% RA\nHR: 96\nBP: 156/88\nTemp: 37.2\nA-E: HS 1+2+0, chest clear, nil oedema.\nLearner Actions\nFaculty Actions\nIntroduce self and confirm patient identity\nSystematic history including SOCRATES for chest pain\nA-E Assessment\nRequests ECG\n\nSim Leader\nProvide history chest pain and progressive shortness of breath\nIf prompted provide PMHx of HTN, pre-diabetes, cardiac FHx\n\nSim Nurse\nPrompt learner to consider analgesia\nProvide ECG only after complete history taking\n\n\n\n\nTransition trigger: structured history and A-E completed, ECG provided, time elapsed\n\nSTAGE 2 \u2013 Differential Diagnosis/Investigations\nRR: 20\nSpO2: 95% RA\nHR: 100\nBP: 136/78\nTemp: 37.2\nA-E: As above; elevated HR, down-trending BP.\nLearner Actions\nFaculty Actions\nInterpretation of ECG\nIdentifies anterior STEMI\nPrescribes appropriate ACS treatments\nPrescribe analgesia/anti-emetic if not done already\nEscalation to registrar/2222 \nSim Leader\nPatient to complain of pain and nausea\nBP down-trending, HR increasing\nQuery diagnosis - \u201cAm I going to die?\u201d\n\nSim Nurse\nProvide ECG when requested\nPrompt learner with patient discomfort\nPrompt learner for anti-emetic if sick\nAsk for most likely diagnosis/differential\n\n\nTransition trigger: Identifies ACS, appropriate treatment prescribed, differential given, escalation, time elapsed\n\n\n\n\n\n\nSIMULATION CHECKLISTScenario 1 \u2013 Anterior STEMISIMULATION CHECKLISTScenario 1 \u2013 Anterior STEMI\nSIMULATION CHECKLIST\nScenario 1 \u2013 Anterior STEMI\nSIMULATION CHECKLIST\nScenario 1 \u2013 Anterior STEMI\nSTAGE 3 \u2013 Patient Deterioration\nRR: 28\nSpO2: 84% RA\nHR: 120\nBP: 116/76\nTemp: 37.2\nA-E: Tachycardia, hypoxia, hypotension. Visibly breathless with bibasal crackles. \nLearner Actions\nFaculty Actions\nRecognise deterioration in patient \nFurther A-E Assessment\nCommence O2 therapy\nRequests ABG\nRequests CXR\nUpdates ECG/commence cardiac monitoring\nEscalates 2222 if not done already\n\n\nSim Leader\nEscalate hypoxia and tachycardia\nReduce blood pressure\nPatient to become increasingly distressed\nDrop sats to 70s if O2 not commenced\n\nSim Nurse\nPrompt learner to recognise patient deterioration\nProvide CXR when requested\nProvide ABG when requested\nIf 2222 not called or alternative help sought \u2013 prompt learner that seems to be time critical emergency\n\n\n\nTransition trigger: CXR requested, repeat A-E assessment underway, time elapsed, calls for senior support/2222\n\nSTAGE 4 \u2013 Deterioration, Escalation, SBAR Handover\nRR: 22\nSpO2: 96% on O2\nHR: 102\nBP: 120/74\nTemp: 37.2\nA-E: Less breathless, normal sats on O2, ongoing bibasal crackles, HR and BP improving.\nLearner Actions\nFaculty Actions\nIdentifies acute pulmonary oedema on CXR\nIdentifies T1RF on ABG\nSuggests IV diuretic\nDeliver SBAR handover\nOffer likely diagnosis and plan\n\nSim Leader\nTake on role of medical registrar arriving\nReceive SBAR handover\nPrompt for differential diagnosis\nPrompt for any missed investigations/interpretation\n\n\nSim Nurse\nReassure patient/acting in background\n\nTransition trigger: Completed handover \u2013 scenario end\n"
}'::jsonb) on conflict(id) do nothing;
commit;

begin;
alter table public.monitors drop constraint if exists monitors_state_check;
alter table public.monitors add constraint monitors_state_check check (
  jsonb_typeof(state)='object' and
  state-array['patient','status','elapsed','anchor','observations','pins','ramp','oxygen','oxygenDevice','oxygenFlow','ventilation','rhythm','revision','updatedAt','alarmAck','released']='{}'::jsonb
);
commit;

begin;
create table public.controller_links(session_id uuid primary key references public.sessions on delete cascade,user_id uuid not null references auth.users on delete cascade,device text not null,seen_at timestamptz not null default now());
create table public.pair_challenges(session_id uuid primary key references public.sessions on delete cascade,token_hash text unique not null,code_hash text unique not null,expires_at timestamptz not null);
create table public.revoked_controllers(session_id uuid references public.sessions on delete cascade,user_id uuid references auth.users on delete cascade,device text,primary key(session_id,user_id,device));
alter table public.revoked_controllers enable row level security;grant all on public.revoked_controllers to service_role;
create table public.pair_attempts(user_id uuid not null references auth.users on delete cascade,at timestamptz not null default now());
create table public.scenario_drafts(user_id uuid not null references auth.users on delete cascade,id text not null,data jsonb not null,updated_at timestamptz default now(),primary key(user_id,id));
alter table public.controller_links enable row level security;
alter table public.pair_challenges enable row level security;
alter table public.pair_attempts enable row level security;
alter table public.scenario_drafts enable row level security;
grant all on public.controller_links,public.pair_challenges,public.pair_attempts,public.scenario_drafts to service_role;
create or replace function public.can_control(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.is_instructor() and exists(select 1 from public.controller_links where session_id=p_id and user_id=auth.uid()) $$;
revoke all on function public.can_control(uuid) from public,anon; grant execute on function public.can_control(uuid) to authenticated,service_role;
create policy paired_faculty on public.sessions for select to authenticated using(public.can_control(id));
create or replace function public.redeem_pair(p_hash text,p_user uuid,p_device text,p_replace boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare challenge public.pair_challenges; active public.controller_links; s public.sessions; begin
 if not exists(select 1 from public.instructors where user_id=p_user) then raise exception 'Instructor access required';end if;
 if length(p_device)<16 or length(p_device)>128 then raise exception 'Invalid controller device';end if;
 -- Bound guesses even for authenticated faculty. Attempts are committed on rejected codes.
 delete from public.pair_attempts where at<now()-interval '10 minutes';
 if (select count(*) from public.pair_attempts where user_id=p_user and at>now()-interval '1 minute')>=10 then return jsonb_build_object('error','Too many attempts; wait one minute');end if;
 insert into public.pair_attempts(user_id) values(p_user);
 select * into challenge from public.pair_challenges where token_hash=p_hash or code_hash=p_hash;
 if not found then return jsonb_build_object('error','Pairing link expired, used or regenerated');end if;
 select * into s from public.sessions where id=challenge.session_id for update;
 select * into challenge from public.pair_challenges where session_id=s.id for update;
 if not found or (challenge.token_hash<>p_hash and challenge.code_hash<>p_hash) or challenge.expires_at<=now() or s.state->>'status'='ended' then return jsonb_build_object('error','Pairing link expired, used or regenerated');end if;
 select * into active from public.controller_links where session_id=s.id;
 if found and (active.device<>p_device or active.user_id<>p_user) and not p_replace then return jsonb_build_object('replacementRequired',true);end if;
 delete from public.revoked_controllers where session_id=s.id and user_id=p_user and device=p_device;
 insert into public.controller_links(session_id,user_id,device) values(s.id,p_user,p_device) on conflict(session_id) do update set user_id=excluded.user_id,device=excluded.device,seen_at=now();
 insert into public.monitor_members(session_id,user_id) values(s.id,p_user) on conflict do nothing;
 delete from public.pair_challenges where session_id=s.id;
 return jsonb_build_object('id',s.id,'code',s.code);
end $$;
create or replace function public.control_commit(p_id uuid,p_actor uuid,p_device text,p_expected bigint,p_state jsonb,p_public jsonb) returns boolean language plpgsql security definer set search_path='' as $$
declare s public.sessions; active public.controller_links; begin
 select * into s from public.sessions where id=p_id for update;
 if not found then raise exception 'Session not found';end if;
 if exists(select 1 from public.revoked_controllers where session_id=p_id and user_id=p_actor and device=p_device) then raise exception 'Controller disconnected; pair this device again';end if;
 if not exists(select 1 from public.instructors where user_id=p_actor) then raise exception 'Instructor required';end if;
 select * into active from public.controller_links where session_id=p_id;
 if found then
  if active.user_id<>p_actor or active.device<>p_device then raise exception 'Another device controls this session';end if;
  update public.controller_links set seen_at=now() where session_id=p_id;
 elsif s.owner<>p_actor then raise exception 'Pair this device first';end if;
 return public.commit_session(p_id,s.owner,p_expected,p_state,p_public);
end $$;
create or replace function public.clear_ended_pairing() returns trigger language plpgsql security definer set search_path='' as $$ begin
 if new.state->>'status'='ended' then delete from public.pair_challenges where session_id=new.id;delete from public.controller_links where session_id=new.id;end if;return new;end $$;
create trigger clear_ended_pairing after update on public.sessions for each row execute function public.clear_ended_pairing();
revoke all on function public.redeem_pair(text,uuid,text,boolean),public.control_commit(uuid,uuid,text,bigint,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.redeem_pair(text,uuid,text,boolean),public.control_commit(uuid,uuid,text,bigint,jsonb,jsonb) to service_role;
alter table public.monitors drop constraint if exists monitors_state_check;
alter table public.monitors add constraint monitors_state_check check(jsonb_typeof(state)='object' and state-array['patient','status','elapsed','anchor','observations','pins','ramp','oxygen','oxygenDevice','oxygenFlow','ventilation','rhythm','perfusion','signalQuality','revision','updatedAt','alarmAck','released']='{}'::jsonb);
commit;

begin;
-- First owner command claims the primary device atomically; direct controllers
-- receive the same one-device restriction as QR-paired controllers.
create or replace function public.control_commit(p_id uuid,p_actor uuid,p_device text,p_expected bigint,p_state jsonb,p_public jsonb) returns boolean language plpgsql security definer set search_path='' as $$
declare s public.sessions; active public.controller_links; begin
 select * into s from public.sessions where id=p_id for update;
 if not found then raise exception 'Session not found';end if;
 if exists(select 1 from public.revoked_controllers where session_id=p_id and user_id=p_actor and device=p_device) then raise exception 'Controller disconnected; pair this device again';end if;
 if not exists(select 1 from public.instructors where user_id=p_actor) then raise exception 'Instructor required';end if;
 select * into active from public.controller_links where session_id=p_id;
 if found then
  if active.user_id<>p_actor or active.device<>p_device then raise exception 'Another device controls this session';end if;
  update public.controller_links set seen_at=now() where session_id=p_id;
 elsif s.owner<>p_actor then raise exception 'Pair this device first';
 else insert into public.controller_links(session_id,user_id,device) values(p_id,p_actor,p_device);end if;
 return public.commit_session(p_id,s.owner,p_expected,p_state,p_public);
end $$;
commit;
